const listModelCallOpeningContentInputs = `-- name: ListModelCallOpeningContentInputs :many
SELECT opening.input_id::uuid AS input_id,
       opening.event_sequence::bigint AS event_sequence
FROM agent_model_call_opening_content_inputs(
  $1,
  $2,
  $3,
  $4
) AS opening(input_id, event_sequence)
ORDER BY opening.event_sequence
`

type ListModelCallOpeningContentInputsParams struct {
	ProjectID          uuid.UUID
	AgentID            uuid.UUID
	TurnID             uuid.UUID
	InputEventSequence int64
}

type ListModelCallOpeningContentInputsRow struct {
	InputID       uuid.UUID
	EventSequence int64
}

func (q *Queries) ListModelCallOpeningContentInputs(ctx context.Context, arg ListModelCallOpeningContentInputsParams) ([]ListModelCallOpeningContentInputsRow, error) {
	rows, err := q.db.Query(ctx, listModelCallOpeningContentInputs,
		arg.ProjectID,
		arg.AgentID,
		arg.TurnID,
		arg.InputEventSequence,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListModelCallOpeningContentInputsRow{}
	for rows.Next() {
		var i ListModelCallOpeningContentInputsRow
		if err := rows.Scan(&i.InputID, &i.EventSequence); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

